require __DIR__.'/app/bootstrap.php';Auth::requireLogin();$pageTitle='Settings';
$s=db()->prepare("SELECT COUNT(*) runs,COALESCE(SUM(cost_usd),0) estimated_cost,COALESCE(SUM(audio_seconds),0) audio_seconds FROM provider_runs pr JOIN transcripts t ON t.id=pr.transcript_id WHERE t.user_id=? AND pr.status='completed'");$s->execute([Auth::id()]);$usage=$s->fetch();
$s=db()->prepare("SELECT provider_name,model_name,COUNT(*) runs,COALESCE(SUM(cost_usd),0) estimated_cost FROM provider_runs pr JOIN transcripts t ON t.id=pr.transcript_id WHERE t.user_id=? AND pr.status='completed' GROUP BY provider_name,model_name ORDER BY runs DESC");$s->execute([Auth::id()]);$providers=$s->fetchAll();
